import { readFile } from 'node:fs';

// Error-first callback: check err before touching data.
readFile('notes.txt', 'utf8', (err, text) => {
    if (err) {
        console.error(err.code, err.message);
        return;
    }
    console.log(text.split('\n').length, 'lines');
});

import { writeFile } from 'node:fs/promises';

const report = { hotel_id: 3, bookings: 12, guests: 27 };

// Objects must be serialized first; writeFile rejects a plain object.
await writeFile('report.json', JSON.stringify(report, null, 2) + '\n');

// Append instead of replace, and fail instead of overwriting:
await writeFile('out.csv', 'hotel_id,bookings\n', { flag: 'a' });
await writeFile('report.json', '{}', { flag: 'wx' }); // EEXIST if it exists

import { appendFile } from 'node:fs/promises';

// One JSON object per line keeps the log parseable later.
const event = { at: new Date().toISOString(), event: 'login', user: 17 };
await appendFile('audit.log', JSON.stringify(event) + '\n');

// Plain text lines, newline included explicitly.
await appendFile('run.log', `${new Date().toISOString()} started\n`);

import { mkdir } from 'node:fs/promises';

// Without recursive, a missing parent fails with ENOENT.
await mkdir('out', { recursive: true });

// Safe to call on every run: no error when the tree exists.
await mkdir('out/reports/2026', { recursive: true });

import { readdir } from 'node:fs/promises';

const entries = await readdir('data', { withFileTypes: true });

for (const entry of entries) {
    if (entry.isDirectory()) console.log('dir ', entry.name);
    else if (entry.isFile()) console.log('file', entry.name);
}

// Plain names when the type is not needed:
const names = await readdir('data');
console.log(names.filter((name) => name.endsWith('.csv')));

import { stat } from 'node:fs/promises';

const info = await stat('bookings.csv');

console.log(info.size);              // bytes, not characters
console.log(info.mtime.toISOString());
console.log(info.isFile(), info.isDirectory());

// Guard before reading a path that might be a folder:
if (info.isDirectory()) throw new Error('expected a file');

import { rm } from 'node:fs/promises';

// Delete one file. Missing file is an error without force.
await rm('out/report.json', { force: true });

// Delete a directory and everything in it.
await rm('out/tmp', { recursive: true, force: true });

import { writeFile, rename, rm } from 'node:fs/promises';
import path from 'node:path';

async function writeAtomic(target, data) {
    // The temp file must sit in the same directory, or rename fails with EXDEV.
    const tmp = path.join(path.dirname(target), `.${path.basename(target)}.tmp`);
    try {
        await writeFile(tmp, data);
        await rename(tmp, target); // replaces the old file in one step
    } catch (err) {
        await rm(tmp, { force: true });
        throw err;
    }
}

await writeAtomic('out/report.json', '{"ok":true}\n');

