import { createReadStream } from 'node:fs';

let lines = 0;
const stream = createReadStream('access.log', { encoding: 'utf8' });

// for await pauses and resumes the stream, so memory stays flat.
for await (const chunk of stream) {
    lines += chunk.split('\n').length - 1;
}
console.log({ lines }); // note: counts only complete newlines in chunks

import { createReadStream, createWriteStream } from 'node:fs';
import { createGzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';

// Copy and compress in one pass, with one error handler.
await pipeline(
    createReadStream('access.log'),
    createGzip(),
    createWriteStream('access.log.gz'),
);

// Cancellation: the signal destroys every stage and releases the handles.
const controller = new AbortController();
await pipeline(createReadStream('big.csv'), createWriteStream('copy.csv'), {
    signal: controller.signal,
});

import { Transform } from 'node:stream';

// Buffer the unfinished tail: a chunk can end in the middle of a line.
const splitLines = new Transform({
    transform(chunk, encoding, callback) {
        this.rest = (this.rest ?? '') + chunk.toString();
        const lines = this.rest.split('\n');
        this.rest = lines.pop();
        callback(null, lines.length ? lines.join('\n') + '\n' : undefined);
    },
    flush(callback) {
        // The last line may arrive without a trailing newline.
        callback(null, this.rest || undefined);
    },
});

import { createReadStream } from 'node:fs';
import readline from 'node:readline';

const rl = readline.createInterface({
    input: createReadStream('access.log', 'utf8'),
    crlfDelay: Infinity, // treat \r\n as one break on every platform
});

let errors = 0;
for await (const line of rl) {
    if (line.includes(' 500 ')) errors += 1;
}
console.log({ errors });
